const getAliases = `-- name: GetAliases :many
SELECT
    alias.id,
    alias.name,
    alias.description,
    alias.created_at,
    alias.updated_at,
    alias.is_deleted,
    alias.user_id
FROM dc.alias
WHERE alias.is_deleted = false
ORDER BY CASE WHEN $1::text <> 'DESC' THEN alias.id END ASC,
    CASE WHEN $1::text = 'DESC' THEN alias.id END DESC
LIMIT $3::int OFFSET ($2::int-1)*$3::int
`

type GetAliasesParams struct {
	Order     string
	Page      int32
	PageLimit int32
}

func (q *Queries) GetAliases(ctx context.Context, arg GetAliasesParams) ([]DcAlias, error) {
	rows, err := q.db.QueryContext(ctx, getAliases, arg.Order, arg.Page, arg.PageLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DcAlias
	for rows.Next() {
		var i DcAlias
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Description,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.IsDeleted,
			&i.UserID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

